"""Seam coverage for the configurable selection-key row (upstream #463/#539).

``selKeyType`` picks the row the engine uses for selection, paging and the
re-attach of the candidate window. The default row stays ``1234567890``; the
0-based ``0123456789`` row lets the 嘸蝦米-style tables reach their tenth
candidate with ``9`` and select with ``0``.
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402
from test_cinbase_selection_keys import synthetic_cin  # noqa: E402


class CinbaseSelKeyConfigTests(CinbaseKeyHarness):

    def three_candidate_table(self, service, perPage=2):
        service.cin = synthetic_cin(
            {"l": ["甲", "乙", "丙"], "b": ["月"]}, {"l": "︙", "b": "月"})
        service.candPerPage = perPage
        service.candPerRow = perPage
        service.candidateView.configure(perPage, perPage)
        service.directShowCand = False
        service.switchPageWithSpace = True

    def test_default_row_is_the_one_based_row(self):
        service = self.activate_chesimplex()
        self.assertEqual(service.cfg.getSelKeys(), "1234567890")
        self.assertEqual(service.selKeys, "1234567890")

    def test_configured_zero_based_row_wins_in_selection(self):
        service = self.activate_chesimplex()
        self.three_candidate_table(service, perPage=9)
        service.cfg.selKeyType = 1
        service.selKeys = service.cfg.getSelKeys()

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)  # open the window

        # 0-based: 0 是第一個, 2 是第三個
        self.assertEqual(self.send(service, ord("0"), 0x30, printable=True), "甲")
        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)
        self.assertEqual(self.send(service, ord("2"), 0x32, printable=True), "丙")

    def test_configured_row_wins_after_a_page_turn(self):
        service = self.activate_chesimplex()
        self.three_candidate_table(service, perPage=2)
        service.cfg.selKeyType = 1
        service.selKeys = service.cfg.getSelKeys()

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)  # open, page 0
        self.send(service, 0x20, 0x20, printable=True)  # page 1: 丙
        self.assertEqual(list(service.candidateList), ["丙"])
        self.assertEqual(self.send(service, ord("0"), 0x30, printable=True), "丙")

    def test_row_is_re_attached_to_the_text_service(self):
        service = self.activate_chesimplex()
        service.cfg.selKeyType = 1
        service.currentReply = {}

        service.checkConfigChange()

        self.assertEqual(service.currentReply.get("setSelKeys"), "0123456789")
        self.assertEqual(service.selKeys, "0123456789")

    def test_out_of_range_index_falls_back_to_the_default_row(self):
        service = self.activate_chesimplex()
        service.cfg.selKeyType = 7
        self.assertEqual(service.cfg.getSelKeys(), "1234567890")
        service.cfg.selKeyType = "x"
        self.assertEqual(service.cfg.getSelKeys(), "1234567890")


if __name__ == "__main__":
    unittest.main()
